(self.CURRICULUM ||= { lessons: [] }).lessons.push(...[{"n": 51, "title": "Lesson 51: ~기도 하고… ~기도 하다", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-51/", "vocab": [{"ko": "억양", "en": "accent", "pos": "noun"}, {"ko": "빚", "en": "debt", "pos": "noun"}, {"ko": "빗", "en": "comb", "pos": "noun"}, {"ko": "솔", "en": "brush", "pos": "noun"}, {"ko": "치약", "en": "toothpaste", "pos": "noun"}, {"ko": "칫솔", "en": "toothbrush", "pos": "noun"}, {"ko": "화학", "en": "chemistry", "pos": "noun"}, {"ko": "철학", "en": "philosophy", "pos": "noun"}, {"ko": "가죽", "en": "leather", "pos": "noun"}, {"ko": "악어", "en": "alligator, crocodile", "pos": "noun"}, {"ko": "발명품", "en": "invention", "pos": "noun"}, {"ko": "스타일", "en": "style", "pos": "noun"}, {"ko": "향수", "en": "perfume", "pos": "noun"}, {"ko": "코", "en": "nose", "pos": "noun"}, {"ko": "콧구멍", "en": "nostril", "pos": "noun"}, {"ko": "양파", "en": "onion", "pos": "noun"}, {"ko": "양말", "en": "socks", "pos": "noun"}, {"ko": "틈", "en": "crack, gap", "pos": "noun"}, {"ko": "시설", "en": "facilities", "pos": "noun"}, {"ko": "개수", "en": "number of things", "pos": "noun"}, {"ko": "명수", "en": "number of people", "pos": "noun"}, {"ko": "대화", "en": "conversation", "pos": "noun"}, {"ko": "빗다", "en": "to comb one's hair", "pos": "verb"}, {"ko": "비교하다", "en": "to compare", "pos": "verb"}, {"ko": "발명하다", "en": "to invent", "pos": "verb"}, {"ko": "끓이다", "en": "to boil", "pos": "verb"}, {"ko": "솔질하다", "en": "to brush", "pos": "verb"}, {"ko": "진학하다", "en": "to go on to (school)", "pos": "verb"}, {"ko": "세다", "en": "to count", "pos": "verb"}, {"ko": "사과하다", "en": "to apologize", "pos": "verb"}, {"ko": "뿌리다", "en": "to sprinkle", "pos": "verb"}, {"ko": "끓다", "en": "to be boiling", "pos": "verb"}, {"ko": "끝없다", "en": "to be endless", "pos": "adjective"}, {"ko": "미묘하다", "en": "to be subtle", "pos": "adjective"}, {"ko": "불행하다", "en": "to be unhappy", "pos": "adjective"}, {"ko": "밉다", "en": "to be hateful, annoying", "pos": "adjective"}], "grammar": [{"point": "~기도 하다 (also / sometimes)", "explanation": "~기도 하다 adds 'also' or 'sometimes' to a whole action or description. Use it when something is true on top of what you would expect, or when it happens now and then rather than always. 영화를 봐요 just says 'I watch movies'. 영화를 보기도 해요 says 'I also watch movies' or 'I sometimes watch movies'.\n\nTo form it, turn the stem into a noun with ~기 (Lesson 29), add the particle ~도 ('also'), then add 하다. 보다 → 보 + 기 → 보기 + 도 → 보기도 해요. 읽다 → 읽기도 해요. Vowel or consonant ending makes no difference. Adjectives work the same way: 밉다 → 밉기도 해요 'is sometimes annoying, too'.\n\nTense and politeness go only on the final 하다: 보기도 했어요 'also watched', 보기도 할 거예요 'will also watch'. A common mistake is putting the tense inside: 봤기도 해요 is wrong.\n\nCompare ~도 on a noun: 영화도 봐요 means 'I watch movies too' (movies as well as other things). 영화를 보기도 해요 puts the 'also' on the whole action.", "examples": [{"ko": "저는 가끔 혼자 영화를 보기도 해요.", "en": "I sometimes watch movies alone, too."}, {"ko": "양파를 자르면 눈물이 나기도 해요.", "en": "Sometimes tears come out when you cut onions."}, {"ko": "그 사람은 화학을 가르치기도 해요.", "en": "That person also teaches chemistry."}, {"ko": "저는 아침에 우유를 끓이기도 해요.", "en": "I sometimes boil milk in the morning."}, {"ko": "그 사람은 가끔 밉기도 해요.", "en": "That person is sometimes annoying, too.", "note": "Adjectives take ~기도 하다 the same way: 밉 + 기도 해요."}, {"ko": "어제는 친구에게 사과하기도 했어요.", "en": "Yesterday I also apologized to my friend.", "note": "Only the final 하다 shows the past: 사과하기도 했어요."}, {"ko": "주말에 운동하기도 해요?", "en": "Do you also exercise on weekends?"}]}, {"point": "~기도 하고 ~기도 하다 (both A and B)", "explanation": "Use this pattern when two things are both true about the same situation: 'A, and also B' or 'both A and B'. It is common for mixed feelings (a movie that was both sad and fun) and for a range of activities you do at different times. The two parts can even be opposites.\n\nForm: stem A + 기도 하고, then stem B + 기도 하다. Only the last 하다 changes for tense and politeness. 읽다, 만나다 → 읽기도 하고 만나기도 해요. Past: 슬프다, 재미있다 → 슬프기도 하고 재미있기도 했어요 (not 슬펐기도 하고).\n\nCompare plain ~고 (Lesson 17): 책을 읽고 친구를 만나요 just lists two actions and can suggest an order, first one and then the other. With ~기도 하고 ~기도 하다 there is no time order. The two things each happen sometimes, or they are two sides of the same thing.", "examples": [{"ko": "저는 주말에 책을 읽기도 하고 친구를 만나기도 해요.", "en": "On weekends I read books and also meet friends."}, {"ko": "그 영화는 슬프기도 하고 재미있기도 했어요.", "en": "That movie was both sad and fun."}, {"ko": "저는 대학교에서 철학을 공부하기도 하고 화학을 공부하기도 했어요.", "en": "At university I studied both philosophy and chemistry."}, {"ko": "이 일은 쉽기도 하고 어렵기도 해요.", "en": "This work is easy in some ways and hard in others."}, {"ko": "혼자 사는 것은 편하기도 하고 외롭기도 해요.", "en": "Living alone is both comfortable and lonely."}, {"ko": "어제는 비가 오기도 하고 눈이 오기도 했어요.", "en": "Yesterday it rained and also snowed.", "note": "The tense sits only on the last 하다: 오기도 하고 … 오기도 했어요."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "저는 주말에 집에서 요리를 ___ 해요.", "answer": "하기도", "options": ["하기도", "해기도", "하도", "하는도"], "en": "On weekends I sometimes cook at home, too.", "why": "Stem + 기 makes a noun, then 도 하다 adds 'also/sometimes'."}, {"type": "fill", "ko": "그 소설은 길기도 하고 어렵___ 했어요.", "answer": "기도", "options": ["기도", "고", "지도", "기를"], "en": "That novel was both long and difficult.", "why": "Both halves of the pattern need 기도: 길기도 하고 어렵기도 하다."}, {"type": "fill", "ko": "저는 아침에 차를 마시기도 하고 커피를 ___.", "answer": "마시기도 해요", "options": ["마시기도 해요", "마시기도 하고", "마셔도 해요", "마시기도 돼요"], "en": "In the morning I drink tea and sometimes coffee.", "why": "The second part ends the sentence, so ~기도 해요."}, {"type": "fill", "ko": "제 형은 화학을 가르치기도 ___ 책을 쓰기도 해요.", "answer": "하고", "options": ["하고", "해고", "하기", "하도"], "en": "My older brother both teaches chemistry and writes books.", "why": "The first ~기도 clause links to the second with 하고."}, {"type": "fill", "ko": "그 사람은 가끔 ___ 해요.", "answer": "밉기도", "options": ["밉기도", "미워도", "밉도", "미기도"], "en": "That person can be annoying sometimes.", "why": "Add 기도 straight to the stem 밉; the ㅂ irregular change only happens before a vowel."}, {"type": "fill", "ko": "물이 끓으면 소금을 ___ 해요.", "answer": "뿌리기도", "options": ["뿌리기도", "뿌려기도", "뿌리도", "뿌리기가"], "en": "When the water boils, I sometimes sprinkle in salt too.", "why": "~기도 하다 attaches to the plain stem 뿌리."}, {"type": "fill", "ko": "혼자 사는 것은 편하기도 하고 ___ 해요.", "answer": "힘들기도", "options": ["힘들기도", "힘드기도", "힘들도", "힘들어도"], "en": "Living alone is both comfortable and hard.", "why": "The ㄹ of 힘들다 stays before 기."}, {"type": "fill", "ko": "어제는 비가 오기도 하고 눈이 오기도 ___.", "answer": "했어요", "options": ["했어요", "해요", "했고", "하기도"], "en": "Yesterday it both rained and snowed.", "why": "Tense goes on the final 하다; 어제 needs past 했어요."}, {"type": "translate", "en": "I sometimes go to the park alone.", "ko": "저는 가끔 혼자 공원에 가기도 해요."}, {"type": "translate", "en": "That bag is both cheap and pretty.", "ko": "그 가방은 싸기도 하고 예쁘기도 해요."}, {"type": "translate", "en": "On weekends I clean my room and also meet friends.", "ko": "주말에는 방을 청소하기도 하고 친구를 만나기도 해요."}, {"type": "translate", "en": "I sometimes boil ramen at night.", "ko": "저는 밤에 라면을 끓이기도 해요."}], "reading": {"ko": "저는 대학생이에요. 저는 한국어를 배우기도 하고 화학을 공부하기도 해요. 수업은 재미있기도 하고 어렵기도 해요. 주말에는 도서관에 가기도 하고 집에서 쉬기도 해요. 가끔 친구들과 한국어로 대화를 하기도 해요. 저는 요리를 잘 못해요. 그래서 밤에는 라면을 끓이기도 해요.", "en": "I am a university student. I learn Korean and also study chemistry. Classes are both fun and difficult. On weekends I sometimes go to the library and sometimes rest at home. Sometimes I also have conversations with friends in Korean. I'm not good at cooking. So at night I sometimes boil ramen.", "questions": [{"q": "이 사람은 무엇을 공부해요?", "a": "한국어하고 화학을 공부해요."}, {"q": "수업은 어때요?", "a": "재미있기도 하고 어렵기도 해요."}, {"q": "주말에 무엇을 해요?", "a": "도서관에 가기도 하고 집에서 쉬기도 해요."}]}}}, {"n": 52, "title": "Lesson 52: Quoting in Korean (~ㄴ/는다고)", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-52/", "vocab": [{"ko": "식신", "en": "big eater", "pos": "noun"}, {"ko": "길이", "en": "length", "pos": "noun"}, {"ko": "밧줄", "en": "rope", "pos": "noun"}, {"ko": "주인공", "en": "main character", "pos": "noun"}, {"ko": "소설가", "en": "novelist", "pos": "noun"}, {"ko": "자동차", "en": "automobile", "pos": "noun"}, {"ko": "시식", "en": "free food sample", "pos": "noun"}, {"ko": "입력", "en": "input", "pos": "noun"}, {"ko": "출력", "en": "output", "pos": "noun"}, {"ko": "현금인출기", "en": "ATM", "pos": "noun"}, {"ko": "시위자", "en": "protester", "pos": "noun"}, {"ko": "불만", "en": "complaint", "pos": "noun"}, {"ko": "정각", "en": "on the hour", "pos": "noun"}, {"ko": "돌아서다", "en": "to turn around", "pos": "verb"}, {"ko": "늘이다", "en": "to lengthen", "pos": "verb"}, {"ko": "가리키다", "en": "to point at", "pos": "verb"}, {"ko": "상상하다", "en": "to imagine", "pos": "verb"}, {"ko": "심다", "en": "to plant", "pos": "verb"}, {"ko": "위로하다", "en": "to console", "pos": "verb"}, {"ko": "조그맣다", "en": "to be tiny", "pos": "adjective"}, {"ko": "월등하다", "en": "to be far superior", "pos": "adjective"}, {"ko": "불만족스럽다", "en": "to be dissatisfied", "pos": "adjective"}, {"ko": "몹시", "en": "very, badly", "pos": "adverb"}, {"ko": "점차", "en": "gradually (written)", "pos": "adverb"}, {"ko": "지금껏", "en": "until now", "pos": "adverb"}], "grammar": [{"point": "Quoting verbs: ~ㄴ/는다고 하다", "explanation": "Use this to report what someone said in your own words: 'he said that...'. The quote drops the speaker's 요 or 습니다. Instead, the quoted verb goes into the plain form used in writing, then ~고 links it to a reporting verb such as 하다 or 말하다. The reporting verb carries the real tense and politeness: 했어요 'said'.\n\nPresent tense, step by step. Stem ends in a vowel → add ㄴ다: 가다 → 간다 → 간다고 했어요. Stem ends in a consonant → add 는다: 먹다 → 먹는다 → 먹는다고 했어요. ㄹ stems drop the ㄹ and take ㄴ다: 살다 → 산다고. Negative 않다 acts like a verb: 먹지 않는다고.\n\nPast tense: past stem + 다고. 하다 → 했 + 다고 → 했다고. 먹다 → 먹었다고. Future: ~(으)ㄹ 거라고 (갈 거라고, 먹을 거라고) or ~겠다고 (가겠다고).\n\nThe tense inside the quote is the tense of the original words. 친구가 간다고 했어요 means my friend said 'I'm going'.", "examples": [{"ko": "친구가 내일 한국에 간다고 했어요.", "en": "My friend said he is going to Korea tomorrow."}, {"ko": "동생이 숙제를 다 했다고 말했어요.", "en": "My younger sibling said they finished all their homework."}, {"ko": "그 소설가가 새 책을 쓸 거라고 했어요.", "en": "The novelist said she will write a new book."}, {"ko": "아이들이 나무를 심는다고 했어요.", "en": "The kids said they are planting trees."}, {"ko": "그 소설가는 서울에 산다고 했어요.", "en": "The novelist said she lives in Seoul.", "note": "살다 drops ㄹ: 살 + ㄴ다고 → 산다고."}, {"ko": "동생이 고기를 먹지 않는다고 했어요.", "en": "My younger sibling said they don't eat meat.", "note": "않다 follows the verb pattern here: 않 + 는다고."}]}, {"point": "Quoting adjectives: ~다고 하다", "explanation": "Adjectives are simpler than verbs. In the plain form, an adjective's present tense is just its dictionary form: 바쁘다, 피곤하다. So you add ~고 straight to it: 바쁘다 → 바쁘다고 했어요. Never add ㄴ/는 to an adjective: 바쁜다고 is wrong.\n\n있다 and 없다, and words built on them like 재미있다 and 맛없다, also take just ~다고: 시간이 없다고 했어요.\n\nPast tense uses 았/었 + 다고, as with verbs: 바쁘다 → 바빴다고. Irregulars change as usual: 춥다 → 추웠다고. For a negative, put 안 in front: 안 비싸다고.\n\nAs always, the reporting verb (하다, 말하다) at the end carries the final tense and politeness.", "examples": [{"ko": "민수가 오늘 너무 피곤하다고 했어요.", "en": "Minsu said he is very tired today."}, {"ko": "선생님이 이 문제가 어렵다고 말했어요.", "en": "The teacher said this problem is difficult."}, {"ko": "친구가 그 방이 조그맣다고 했어요.", "en": "My friend said that room is tiny."}, {"ko": "친구가 오늘 시간이 없다고 했어요.", "en": "My friend said she doesn't have time today."}, {"ko": "친구가 어제 날씨가 너무 추웠다고 했어요.", "en": "My friend said the weather was really cold yesterday.", "note": "춥다 is ㅂ irregular: 춥 → 추웠다고."}, {"ko": "언니가 그 식당이 안 비싸다고 했어요.", "en": "My older sister said that restaurant isn't expensive."}]}, {"point": "Quoting 이다: ~(이)라고 하다", "explanation": "When the original sentence was 'X is Y' with 이다, the quote ends in ~(이)라고 instead of ~다고. Noun ends in a consonant → 이라고: 학생 → 학생이라고. Noun ends in a vowel → 라고: 의사 → 의사라고. A common mistake is 학생이다고, which is wrong.\n\nThe negative 아니다 becomes 아니라고. The noun before it keeps 이/가 as usual: 학생이 아니라고 했어요.\n\nPast tense: consonant → 이었다고 (선생님이었다고), vowel → 였다고 (친구였다고).\n\nThis form is also how you give a name: 저는 김민수라고 합니다 'I'm called Kim Minsu'. Statements with nouns use ~(이)라고; later you will see questions use ~(이)냐고.", "examples": [{"ko": "그 남자가 자기가 의사라고 했어요.", "en": "That man said he is a doctor."}, {"ko": "친구가 이것이 자기 가방이라고 했어요.", "en": "My friend said this is her bag."}, {"ko": "그 사람은 학생이 아니라고 했어요.", "en": "That person said he is not a student."}, {"ko": "저는 김민수라고 합니다.", "en": "My name is Kim Minsu."}, {"ko": "할머니가 젊었을 때 선생님이었다고 했어요.", "en": "Grandma said she was a teacher when she was young.", "note": "Past after a consonant: 선생님 + 이었다고."}, {"ko": "민수가 그 사람이 자기 친구였다고 했어요.", "en": "Minsu said that person was his friend.", "note": "Past after a vowel: 친구 + 였다고."}]}, {"point": "Other verbs used with quotes (생각하다, 믿다, 약속하다, 부르다)", "explanation": "A ~다고 or ~(이)라고 clause works like a 'that...' clause in English. So it can come before verbs of thinking and believing, not just saying. 생각하다: 재미있다고 생각해요 'I think (that) it's fun'. 믿다: 이길 거라고 믿어요 'I believe we'll win'. The quoted part follows the same rules as before: ㄴ/는다 for verbs, 다 for adjectives, (이)라고 for nouns.\n\n약속하다 (promise) usually takes a future quote: 갚겠다고 약속했어요 'promised to pay back'. Here ~겠다 shows the speaker's firm will: 'I will do it'.\n\n부르다 (call) pairs with a noun quote: A를 B(이)라고 부르다 'call A B'. 부르다 is irregular: 부르 + 어요 → 불러요.\n\nTo say you don't think something, negate 생각하다 or the quote: 어렵다고 생각하지 않아요 or 어렵지 않다고 생각해요.", "examples": [{"ko": "저는 이 영화가 재미있다고 생각해요.", "en": "I think this movie is fun."}, {"ko": "저는 우리 팀이 이길 거라고 믿어요.", "en": "I believe our team will win."}, {"ko": "내일까지 빚을 갚겠다고 약속했어요.", "en": "I promised to pay back the debt by tomorrow."}, {"ko": "한국 사람들은 이것을 김밥이라고 불러요.", "en": "Koreans call this gimbap."}, {"ko": "친구들이 저를 식신이라고 불러요.", "en": "My friends call me a big eater.", "note": "부르다 is irregular: 부르 + 어요 → 불러요."}, {"ko": "저는 그 문제가 어렵지 않다고 생각해요.", "en": "I think that problem isn't difficult."}]}, {"point": "Asking with quotes: 뭐라고? / ~다고요?", "explanation": "Two quick conversation uses of quotes. First, 뭐 'what' + 라고 asks what someone said: 뭐라고 했어요? 'What did he say?'. 뭐 ends in a vowel, so it takes 라고. On its own, 뭐라고요? is a polite 'Sorry, what did you say?'. Said sharply, it can sound like 'What did you just say?!', so mind your tone.\n\nThe same 뭐라고 asks what something is called: 이것을 한국어로 뭐라고 해요?\n\nSecond, you can repeat what you heard as a quote, add 요 and raise your tone to check it or show surprise: 시험이 있다고요? 'You said there's a test?'. The usual quote rules apply: verbs → ㄴ/는다고요 (그만둔다고요?), adjectives and 있다/없다 → 다고요 (있다고요?), nouns → (이)라고요 (의사라고요?).", "examples": [{"ko": "선생님이 뭐라고 했어요?", "en": "What did the teacher say?"}, {"ko": "뭐라고요?", "en": "What did you say?"}, {"ko": "내일 시험이 있다고요?", "en": "You said there's a test tomorrow?"}, {"ko": "이것을 한국어로 뭐라고 해요?", "en": "What is this called in Korean?"}, {"ko": "민수가 회사를 그만둔다고요?", "en": "Minsu is quitting his job? Did I hear that right?"}, {"ko": "그 사람이 의사라고요?", "en": "That person is a doctor? Really?"}]}, {"point": "Quoted clause before a noun: ~ㄴ/는다는 것/사실/소문", "explanation": "Sometimes you want to talk about a piece of news itself: 'the rumor that...', 'the fact that...'. Korean takes the quote ~다고 하는 ('that is said to...') and shortens it to ~다는 in front of the noun. Common nouns are 것, 사실 (fact), 소문 (rumor), 말 (words) and 이야기 (story).\n\nBuild the quote first, then change 다고 to 다는:\n그만두다 → 그만둔다고 → 그만둔다는 소문\n많다 → 많다고 → 많다는 사실\n결혼했다 → 결혼했다고 → 결혼했다는 것\nFor nouns, (이)라고 becomes (이)라는: 의사라고 → 의사라는 사실.\n\nCompare plain ~는 것 (Lesson 26): 회사를 그만두는 것 just describes the action. 회사를 그만둔다는 소문 marks it as information someone said or heard.", "examples": [{"ko": "그 사람이 회사를 그만둔다는 소문을 들었어요.", "en": "I heard a rumor that he is quitting the company."}, {"ko": "친구에게 빚이 많다는 사실을 몰랐어요.", "en": "I didn't know that my friend has a lot of debt."}, {"ko": "언니가 결혼했다는 것을 어제 알았어요.", "en": "I found out yesterday that my sister got married."}, {"ko": "그 사람이 의사라는 사실을 아무도 몰랐어요.", "en": "Nobody knew that he was a doctor.", "note": "With 이다 the form is ~(이)라는: 의사 + 라는."}, {"ko": "내일 비가 온다는 말을 들었어요.", "en": "I heard that it's going to rain tomorrow."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "친구가 내일 부산에 ___ 했어요.", "answer": "간다고", "options": ["간다고", "가다고", "가는다고", "갔다고"], "en": "My friend said he is going to Busan tomorrow.", "why": "가 ends in a vowel, so present-tense quoting adds ㄴ다고; 내일 rules out the past."}, {"type": "fill", "ko": "민수가 매일 아침을 ___ 했어요.", "answer": "먹는다고", "options": ["먹는다고", "먹다고", "먹은다고", "먹이라고"], "en": "Minsu said he eats breakfast every day.", "why": "A verb stem ending in a consonant takes 는다고."}, {"type": "fill", "ko": "동생이 이 신발이 너무 ___ 했어요.", "answer": "조그맣다고", "options": ["조그맣다고", "조그만다고", "조그맣는다고", "조그매다고"], "en": "My younger sibling said these shoes are too tiny.", "why": "Adjectives in the present just add 다고 to the stem."}, {"type": "fill", "ko": "그 사람이 자기가 ___ 했어요.", "answer": "소설가라고", "options": ["소설가라고", "소설가이라고", "소설가다고", "소설가는다고"], "en": "That person said he is a novelist.", "why": "A noun + 이다 is quoted with (이)라고; 소설가 ends in a vowel, so 라고."}, {"type": "fill", "ko": "친구가 이 가방이 자기 것이 ___ 했어요.", "answer": "아니라고", "options": ["아니라고", "아니다고", "안이라고", "아닌다고"], "en": "My friend said this bag isn't hers.", "why": "아니다 is quoted as 아니라고, like 이다."}, {"type": "fill", "ko": "저는 그 소설이 아주 ___ 생각해요.", "answer": "재미있다고", "options": ["재미있다고", "재미있는다고", "재미있이라고", "재미있자고"], "en": "I think that novel is very interesting.", "why": "재미있다 is an adjective, so the quote is just stem + 다고 before 생각하다."}, {"type": "fill", "ko": "사람들이 그 남자를 식신___ 불러요.", "answer": "이라고", "options": ["이라고", "라고", "다고", "이다고"], "en": "People call that man a 'big eater'.", "why": "부르다 'to call' uses (이)라고; 식신 ends in a consonant, so 이라고."}, {"type": "fill", "ko": "그 가수가 결혼했___ 소문을 들었어요.", "answer": "다는", "options": ["다는", "다고", "는다는", "다른"], "en": "I heard a rumor that the singer got married.", "why": "Before a noun like 소문, the quote ends in 다는 (short for 다고 하는)."}, {"type": "translate", "en": "My friend said she is busy today.", "ko": "친구가 오늘 바쁘다고 했어요."}, {"type": "translate", "en": "Minsu said he planted a tree yesterday.", "ko": "민수가 어제 나무를 심었다고 했어요."}, {"type": "translate", "en": "What did the teacher say?", "ko": "선생님이 뭐라고 하셨어요?"}, {"type": "translate", "en": "I promised my friend I would come early tomorrow.", "ko": "친구에게 내일 일찍 오겠다고 약속했어요."}], "reading": {"ko": "어제 친구 지민이를 만났어요. 지민이는 요즘 소설을 쓴다고 했어요. 소설의 주인공은 작은 개라고 했어요. 저는 그 이야기가 재미있다고 생각했어요. 지민이는 다음 달에 소설을 다 쓸 거라고 했어요. 그리고 저에게 제일 먼저 보여 주겠다고 약속했어요.", "en": "Yesterday I met my friend Jimin. Jimin said she is writing a novel these days. She said the main character of the novel is a small dog. I thought that story was interesting. Jimin said she will finish writing the novel next month. And she promised to show it to me first.", "questions": [{"q": "지민이는 요즘 뭘 한다고 했어요?", "a": "소설을 쓴다고 했어요."}, {"q": "소설의 주인공은 뭐예요?", "a": "작은 개예요."}, {"q": "지민이는 언제 소설을 다 쓸 거라고 했어요?", "a": "다음 달에 다 쓸 거라고 했어요."}]}}}, {"n": 53, "title": "Lesson 53: Quoting Different Endings: ~자고, ~(으/느)냐고", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-53/", "vocab": [{"ko": "냉동실", "en": "freezer", "pos": "noun"}, {"ko": "반팔", "en": "short sleeves", "pos": "noun"}, {"ko": "며느리", "en": "daughter in law", "pos": "noun"}, {"ko": "사위", "en": "son in law", "pos": "noun"}, {"ko": "턱받이", "en": "bib", "pos": "noun"}, {"ko": "침", "en": "saliva, spit", "pos": "noun"}, {"ko": "남", "en": "others, strangers", "pos": "noun"}, {"ko": "신사", "en": "gentleman", "pos": "noun"}, {"ko": "숙녀", "en": "lady", "pos": "noun"}, {"ko": "지진", "en": "earthquake", "pos": "noun"}, {"ko": "곳곳", "en": "here and there, all over", "pos": "noun"}, {"ko": "앞날", "en": "the future", "pos": "noun"}, {"ko": "흘리다", "en": "to spill, shed", "pos": "verb"}, {"ko": "뱉다", "en": "to spit out", "pos": "verb"}, {"ko": "대하다", "en": "to treat", "pos": "verb"}, {"ko": "불평하다", "en": "to complain", "pos": "verb"}, {"ko": "조르다", "en": "to pester", "pos": "verb"}, {"ko": "파괴하다", "en": "to destroy", "pos": "verb"}, {"ko": "편안하다", "en": "to be comfortable (at ease, peaceful)", "pos": "adjective"}, {"ko": "쾌적하다", "en": "to be pleasant (environment, air)", "pos": "adjective"}, {"ko": "함부로", "en": "carelessly, rudely", "pos": "adverb"}, {"ko": "우연히", "en": "by chance", "pos": "adverb"}], "grammar": [{"point": "Quoting suggestions: ~자고 하다", "explanation": "Use this to report a suggestion: someone said 'let's...'. The original might have been 가자, 갑시다 or 가요 used as 'let's go'. In a quote, all of these become the plain ~자 (Lesson 44) + 고.\n\nForm: stem + 자고. There is no vowel/consonant split: 가다 → 가자고, 먹다 → 먹자고, 만들다 → 만들자고. The reporting verb, usually 하다, carries tense and politeness.\n\nFor 'let's not', use stem + 지 말자고: 나가지 말자고 했어요.\n\nCompare with statement quotes: 간다고 했어요 means 'he said he is going'. 가자고 했어요 means 'he suggested we go'.", "examples": [{"ko": "친구가 같이 영화를 보자고 했어요.", "en": "My friend suggested we watch a movie together."}, {"ko": "남자 친구가 주말에 바다에 가자고 했어요.", "en": "My boyfriend suggested we go to the sea this weekend."}, {"ko": "동생이 저녁에 피자를 먹자고 했어요.", "en": "My younger sibling suggested we eat pizza for dinner."}, {"ko": "친구가 오늘은 밖에 나가지 말자고 했어요.", "en": "My friend suggested we not go out today.", "note": "'Let's not' is ~지 말자고."}, {"ko": "언니가 같이 사진을 찍자고 했어요.", "en": "My older sister suggested we take a photo together."}, {"ko": "누가 먼저 가자고 했어요?", "en": "Who suggested going first?"}]}, {"point": "Quoting questions with verbs: ~(느)냐고", "explanation": "Use this to report a question someone asked: 'he asked if...' or 'she asked where...'. The reporting verb is usually 묻다 or 물어보다. 묻다 is ㄷ irregular: 묻 + 었어요 → 물었어요.\n\nForm: verb stem + 냐고 (casual, most common in speech) or + 느냐고 (more formal, often written). There is no vowel/consonant split: 가다 → 가냐고, 먹다 → 먹냐고 (or 먹느냐고). ㄹ stems drop the ㄹ: 살다 → 사냐고. 있다 and 없다 work like verbs here: 있냐고, 없냐고.\n\nPast: past stem + 냐고: 먹었냐고. Future: ~(으)ㄹ 거냐고: 할 거냐고.\n\nQuestion words stay inside the quote: 어디에 가냐고, 뭘 먹냐고. Without a question word, translate it as 'asked if' or 'asked whether'.", "examples": [{"ko": "엄마가 저에게 밥을 먹었냐고 물어봤어요.", "en": "Mom asked me if I had eaten."}, {"ko": "친구가 저에게 어디에 가냐고 물어봤어요.", "en": "My friend asked me where I was going."}, {"ko": "의사가 저에게 담배를 피우냐고 물어봤어요.", "en": "The doctor asked me if I smoke."}, {"ko": "친구가 저에게 어디에 사냐고 물어봤어요.", "en": "My friend asked me where I live.", "note": "살다 drops ㄹ: 살 + 냐고 → 사냐고."}, {"ko": "동생이 저에게 시간이 있냐고 물었어요.", "en": "My younger sibling asked me if I had time.", "note": "묻다 is ㄷ irregular: 묻 → 물었어요."}, {"ko": "친구가 저에게 내일 뭘 할 거냐고 물어봤어요.", "en": "My friend asked me what I'm going to do tomorrow."}]}, {"point": "Quoting questions with adjectives: ~(으)냐고", "explanation": "Adjectives follow the textbook pattern ~(으)냐고. Stem ends in a consonant → 으냐고: 넓다 → 넓으냐고, 좋다 → 좋으냐고. Stem ends in a vowel → 냐고: 바쁘다 → 바쁘냐고, 아프다 → 아프냐고.\n\nIn everyday speech most people drop the 으 and use 냐고 for every adjective: 넓냐고, 좋냐고. Both are understood. Words ending in 있다/없다 (맛있다, 재미없다) take 냐고: 맛있냐고.\n\nIrregulars: ㄹ stems drop the ㄹ: 멀다 → 머냐고. ㅂ irregulars change before 으: 춥다 → 추우냐고 (casual 춥냐고).\n\nPast tense is the same for every adjective: 았/었 + 냐고 → 바빴냐고, 어려웠냐고.", "examples": [{"ko": "친구가 저에게 요즘 바쁘냐고 물어봤어요.", "en": "My friend asked me if I'm busy these days."}, {"ko": "그 사람이 방이 넓으냐고 물어봤어요.", "en": "That person asked if the room is big."}, {"ko": "엄마가 음식이 맛있냐고 물어봤어요.", "en": "Mom asked if the food was tasty."}, {"ko": "친구가 저에게 시험이 어려웠냐고 물어봤어요.", "en": "My friend asked me if the exam was hard."}, {"ko": "친구가 학교가 집에서 머냐고 물어봤어요.", "en": "My friend asked if school is far from home.", "note": "멀다 drops ㄹ: 멀 + 냐고 → 머냐고."}, {"ko": "의사가 어디가 아프냐고 물어봤어요.", "en": "The doctor asked where it hurts."}]}, {"point": "Quoting questions with 이다: ~(이)냐고", "explanation": "For questions like 'Are you a student?' or 'What is this?', the 이다 at the end becomes ~(이)냐고 in the quote. Noun ends in a consonant → 이냐고: 학생 → 학생이냐고. Noun ends in a vowel → 냐고: 의사 → 의사냐고, 뭐 → 뭐냐고, 누구 → 누구냐고.\n\nThe negative 아니다 becomes 아니냐고: 학생이 아니냐고.\n\nPast: consonant → 이었냐고, vowel → 였냐고: 누구였냐고.\n\nRemember the noun family: statements use ~(이)라고, questions use ~(이)냐고.", "examples": [{"ko": "그 사람이 저에게 학생이냐고 물어봤어요.", "en": "That person asked me if I was a student."}, {"ko": "친구가 이게 뭐냐고 물어봤어요.", "en": "My friend asked what this was."}, {"ko": "선생님이 그 남자가 누구냐고 물어봤어요.", "en": "The teacher asked who that man was."}, {"ko": "친구가 저에게 그 사람이 남자 친구냐고 물어봤어요.", "en": "My friend asked me if that guy was my boyfriend."}, {"ko": "엄마가 어제 만난 사람이 누구였냐고 물어봤어요.", "en": "Mom asked who the person I met yesterday was.", "note": "Past after a vowel: 누구 + 였냐고."}, {"ko": "그 사람이 저에게 한국 사람이 아니냐고 물어봤어요.", "en": "That person asked me if I wasn't Korean."}]}, {"point": "Direct quotes: \"...\"라고 하다", "explanation": "A direct quote repeats someone's exact words, like using quotation marks in English. Put the words in quotation marks, add 라고 (or 하고), then 하다 or 말하다: \"안녕하세요\"라고 했어요.\n\nNothing inside the quotation marks changes. The speech level, 요 and tense stay exactly as they were said. Compare the same words both ways: direct \"배고파요\"라고 했어요, indirect 배고프다고 했어요.\n\nIn a direct quote it is always 라고, even after a consonant: \"감사합니다\"라고. 하고 also works, and is common in speech.", "examples": [{"ko": "아이가 \"배고파요\"라고 말했어요.", "en": "The child said, \"I'm hungry.\""}, {"ko": "그 남자가 \"안녕하세요\"라고 했어요.", "en": "The man said, \"Hello.\""}, {"ko": "엄마가 \"빨리 와\"라고 했어요.", "en": "Mom said, \"Come quickly.\""}, {"ko": "그 신사가 \"감사합니다\"라고 했어요.", "en": "The gentleman said, \"Thank you.\"", "note": "Direct quotes always use 라고, even after a consonant."}, {"ko": "친구가 \"어디 가?\"라고 물어봤어요.", "en": "My friend asked, \"Where are you going?\""}, {"ko": "선생님이 \"숙제를 내일까지 하세요\"라고 말했어요.", "en": "The teacher said, \"Do your homework by tomorrow.\""}]}], "workbook": {"exercises": [{"type": "fill", "ko": "친구가 공원에서 같이 ___ 했어요.", "answer": "걷자고", "options": ["걷자고", "걸어자고", "걸으자고", "걷으자고"], "en": "My friend suggested we walk together in the park.", "why": "~자고 goes straight onto the stem; 걷다 only changes before a vowel."}, {"type": "fill", "ko": "동생이 저녁에 라면을 ___ 했어요.", "answer": "먹자고", "options": ["먹자고", "먹으자고", "먹자라고", "먹는자고"], "en": "My younger sibling suggested we eat ramen for dinner.", "why": "Suggestions are quoted with stem + 자고, with no 으 after a consonant."}, {"type": "fill", "ko": "친구가 저에게 점심을 ___ 물어봤어요.", "answer": "먹었냐고", "options": ["먹었냐고", "먹었다고", "먹었자고", "먹었라고"], "en": "My friend asked me if I had eaten lunch.", "why": "A reported question takes 냐고, here after the past 먹었."}, {"type": "fill", "ko": "그 사람이 저에게 어디에 ___ 물어봤어요.", "answer": "사냐고", "options": ["사냐고", "살냐고", "살으냐고", "산다고"], "en": "That person asked me where I live.", "why": "The ㄹ of 살다 drops before ㄴ, so 사냐고."}, {"type": "fill", "ko": "호텔 직원이 방이 ___ 물어봤어요.", "answer": "편안하냐고", "options": ["편안하냐고", "편안하자고", "편안한다고", "편안하라고"], "en": "The hotel employee asked if the room was comfortable.", "why": "A quoted question with an adjective ends in 냐고 before 물어보다."}, {"type": "fill", "ko": "가게 주인이 저에게 한국 사람___ 물어봤어요.", "answer": "이냐고", "options": ["이냐고", "냐고", "이라고", "이자고"], "en": "The shop owner asked me if I was Korean.", "why": "A question with 이다 is quoted as (이)냐고; 사람 ends in a consonant, so 이냐고."}, {"type": "fill", "ko": "친구가 저에게 그 신사가 ___ 물어봤어요.", "answer": "누구냐고", "options": ["누구냐고", "누구이냐고", "누구라고", "누구자고"], "en": "My friend asked me who that gentleman was.", "why": "누구 ends in a vowel, so 이다 shrinks to 냐고."}, {"type": "fill", "ko": "그 숙녀가 \"감사합니다\"___ 말했어요.", "answer": "라고", "options": ["라고", "이라고", "다고", "자고"], "en": "The lady said, \"Thank you.\"", "why": "A direct quote in quotation marks always takes 라고, whatever it ends in."}, {"type": "translate", "en": "My friend suggested we drink coffee.", "ko": "친구가 커피를 마시자고 했어요."}, {"type": "translate", "en": "Mom asked me if I was cold.", "ko": "엄마가 저에게 춥냐고 물어보셨어요."}, {"type": "translate", "en": "The child said, \"I'm sorry.\"", "ko": "아이가 \"미안해요\"라고 말했어요."}, {"type": "translate", "en": "My older sister asked me where I went yesterday.", "ko": "언니가 저에게 어제 어디에 갔냐고 물어봤어요."}], "reading": {"ko": "어제 제 친구 민수가 저에게 전화했어요. 민수는 저에게 요즘 바쁘냐고 물어봤어요. 저는 조금 바쁘다고 했어요. 민수는 주말에 같이 영화를 보자고 했어요. 저는 무슨 영화냐고 물어봤어요. 민수는 \"슬픈 영화야\"라고 말했어요. 저는 슬픈 영화를 싫어해요. 그래서 다른 영화를 보자고 했어요.", "en": "Yesterday my friend Minsu called me. Minsu asked me if I was busy these days. I said I was a little busy. Minsu suggested we watch a movie together on the weekend. I asked what movie it was. Minsu said, \"It's a sad movie.\" I don't like sad movies. So I suggested we watch a different movie.", "questions": [{"q": "민수는 무엇을 하자고 했어요?", "a": "주말에 같이 영화를 보자고 했어요."}, {"q": "민수는 무슨 영화라고 했어요?", "a": "슬픈 영화라고 했어요."}, {"q": "저는 왜 다른 영화를 보자고 했어요?", "a": "슬픈 영화를 싫어하기 때문이에요."}]}}}, {"n": 54, "title": "Lesson 54: Quoted Imperative Sentences: ~(으)라고", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-54/", "vocab": [{"ko": "의사소통", "en": "communication", "pos": "noun"}, {"ko": "조각", "en": "piece, slice", "pos": "noun"}, {"ko": "지도교사", "en": "guidance counselor", "pos": "noun"}, {"ko": "원어민", "en": "native speaker", "pos": "noun"}, {"ko": "자막", "en": "subtitles", "pos": "noun"}, {"ko": "식중독", "en": "food poisoning", "pos": "noun"}, {"ko": "존댓말", "en": "honorific speech", "pos": "noun"}, {"ko": "오랜만", "en": "a long time (since)", "pos": "noun"}, {"ko": "먹이다", "en": "to feed", "pos": "verb"}, {"ko": "뛰다", "en": "to run", "pos": "verb"}, {"ko": "운영하다", "en": "to run, operate", "pos": "verb"}, {"ko": "갱신하다", "en": "to renew", "pos": "verb"}, {"ko": "토하다", "en": "to throw up", "pos": "verb"}, {"ko": "과장하다", "en": "to exaggerate", "pos": "verb"}, {"ko": "분석하다", "en": "to analyze", "pos": "verb"}, {"ko": "올라타다", "en": "to get on, board", "pos": "verb"}, {"ko": "참석하다", "en": "to attend", "pos": "verb"}, {"ko": "자유롭다", "en": "to be free", "pos": "adjective"}, {"ko": "와중", "en": "midst, meanwhile", "pos": "other"}], "grammar": [{"point": "Quoting commands: ~(으)라고 하다", "explanation": "Use this to report an order or instruction: 'she told me to...'. The original might have been polite (드세요, 읽으세요) or casual (먹어, 읽어라). In a quote they all become ~(으)라고.\n\nForm: stem ends in a vowel → 라고: 자다 → 자라고, 마시다 → 마시라고. Stem ends in a consonant → 으라고: 읽다 → 읽으라고. ㄹ stems take 라고 directly: 만들다 → 만들라고. ㄷ irregulars change: 듣다 → 들으라고.\n\nThe person told to do it takes ~에게 or ~한테. The command itself has no tense; the tense goes on the reporting verb: 했어요.\n\nDon't mix up three similar quotes. 간다고 했어요 = said he is going (statement). 가자고 했어요 = suggested we go (suggestion). 가라고 했어요 = told me to go (command).", "examples": [{"ko": "선생님이 학생들에게 책을 읽으라고 했어요.", "en": "The teacher told the students to read the book."}, {"ko": "엄마가 저에게 일찍 자라고 했어요.", "en": "Mom told me to go to bed early."}, {"ko": "의사가 저에게 물을 많이 마시라고 했어요.", "en": "The doctor told me to drink a lot of water."}, {"ko": "부장님이 회의에 참석하라고 했어요.", "en": "The manager told me to attend the meeting."}, {"ko": "엄마가 저에게 저녁을 만들라고 했어요.", "en": "Mom told me to make dinner.", "note": "ㄹ stems keep the ㄹ and add 라고: 만들 + 라고."}, {"ko": "선생님이 원어민의 발음을 잘 들으라고 했어요.", "en": "The teacher told us to listen carefully to native speakers' pronunciation.", "note": "듣다 is ㄷ irregular: 듣 → 들 + 으라고."}]}, {"point": "Quoting negative commands: ~지 말라고 하다", "explanation": "Use this to report a negative command: 'he told me not to...'. The originals 가지 마세요, 가지 마 and 가지 마라 all become 가지 말라고 in a quote.\n\nForm: stem + 지 (no vowel/consonant split), then 말라고. 말다 is an ㄹ stem, so it adds 라고 directly: 말 + 라고 → 말라고. 먹다 → 먹지 말라고, 가다 → 가지 말라고.\n\nA common mistake is 안 가라고. Commands can't use 안, so 'told me not to go' is 가지 말라고 했어요.\n\nCompare: 가지 말자고 했어요 = suggested we not go. 가지 말라고 했어요 = told me not to go.", "examples": [{"ko": "엄마가 저에게 늦게 오지 말라고 했어요.", "en": "Mom told me not to come home late."}, {"ko": "선생님이 수업 시간에 떠들지 말라고 했어요.", "en": "The teacher told us not to chat during class."}, {"ko": "의사가 저에게 술을 마시지 말라고 했어요.", "en": "The doctor told me not to drink alcohol."}, {"ko": "아빠가 남에게 함부로 말하지 말라고 했어요.", "en": "Dad told me not to speak rudely to others."}, {"ko": "선생님이 저에게 걱정하지 말라고 했어요.", "en": "The teacher told me not to worry."}, {"ko": "의사가 저에게 매운 음식을 먹지 말라고 했어요.", "en": "The doctor told me not to eat spicy food."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "선생님이 학생들에게 한국 영화를 ___ 하셨어요.", "answer": "보라고", "options": ["보라고", "보으라고", "봐라고", "보다고"], "en": "The teacher told the students to watch a Korean movie.", "why": "Commands are quoted with (으)라고; 보 ends in a vowel, so 라고."}, {"type": "fill", "ko": "의사 선생님이 저에게 약을 ___ 하셨어요.", "answer": "먹으라고", "options": ["먹으라고", "먹라고", "먹어라고", "먹자고"], "en": "The doctor told me to take the medicine.", "why": "먹 ends in a consonant, so the command quote is 으라고."}, {"type": "fill", "ko": "엄마가 저에게 여권을 ___ 하셨어요.", "answer": "갱신하라고", "options": ["갱신하라고", "갱신해라고", "갱신하으라고", "갱신하다고"], "en": "Mom told me to renew my passport.", "why": "하다 verbs end in a vowel, so the command quote is 하라고."}, {"type": "fill", "ko": "친구가 저에게 그 영화를 ___ 말라고 했어요.", "answer": "보지", "options": ["보지", "보고", "보기", "봐서"], "en": "My friend told me not to watch that movie.", "why": "A quoted 'don't' is stem + 지 말라고."}, {"type": "fill", "ko": "아빠가 저에게 함부로 말하지 ___ 하셨어요.", "answer": "말라고", "options": ["말라고", "마라고", "말으라고", "않으라고"], "en": "Dad told me not to talk rudely.", "why": "The negative command quote uses 말다 → 말라고; the ㄹ stays."}, {"type": "fill", "ko": "원어민 친구가 저에게 존댓말을 ___ 했어요.", "answer": "쓰라고", "options": ["쓰라고", "써라고", "쓰으라고", "쓰다고"], "en": "My native-speaker friend told me to use honorific speech.", "why": "쓰 ends in a vowel, so the command quote is 쓰라고."}, {"type": "fill", "ko": "선생님이 학생들에게 빨리 ___ 하셨어요.", "answer": "뛰라고", "options": ["뛰라고", "뛰으라고", "뛰어라고", "뛰다고"], "en": "The teacher told the students to run fast.", "why": "Add 라고 directly to the vowel stem 뛰."}, {"type": "fill", "ko": "엄마가 동생___ 음식을 흘리지 말라고 하셨어요.", "answer": "에게", "options": ["에게", "을", "이", "에서"], "en": "Mom told my younger sibling not to spill food.", "why": "The person who gets the order is marked with 에게."}, {"type": "translate", "en": "My friend told me to come quickly.", "ko": "친구가 저에게 빨리 오라고 했어요."}, {"type": "translate", "en": "The teacher told us not to exaggerate.", "ko": "선생님이 우리에게 과장하지 말라고 하셨어요."}, {"type": "translate", "en": "Mom told me to clean my room.", "ko": "엄마가 저에게 방을 청소하라고 하셨어요."}, {"type": "translate", "en": "The doctor told me not to eat spicy food.", "ko": "의사 선생님이 저에게 매운 음식을 먹지 말라고 하셨어요."}], "reading": {"ko": "지난주에 저는 식중독에 걸렸어요. 밤에 배가 아파서 토했어요. 다음 날 병원에 갔어요. 의사 선생님이 저에게 물을 많이 마시라고 하셨어요. 그리고 매운 음식을 먹지 말라고 하셨어요. 엄마는 저에게 집에서 쉬라고 하셨어요. 그래서 저는 학교에 가지 않고 집에서 쉬었어요.", "en": "Last week I got food poisoning. At night my stomach hurt, so I threw up. The next day I went to the hospital. The doctor told me to drink a lot of water. And he told me not to eat spicy food. Mom told me to rest at home. So I didn't go to school and rested at home.", "questions": [{"q": "이 사람은 왜 병원에 갔어요?", "a": "식중독에 걸려서 병원에 갔어요."}, {"q": "의사 선생님이 뭐라고 하셨어요?", "a": "물을 많이 마시라고 하셨어요. 그리고 매운 음식을 먹지 말라고 하셨어요."}, {"q": "엄마는 뭐라고 하셨어요?", "a": "집에서 쉬라고 하셨어요."}]}}}, {"n": 55, "title": "Lesson 55: Quoting 주다 with ~아/어 달라고", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-55/", "vocab": [{"ko": "세대", "en": "generation", "pos": "noun"}, {"ko": "공무원", "en": "civil servant", "pos": "noun"}, {"ko": "창고", "en": "warehouse", "pos": "noun"}, {"ko": "조사", "en": "investigation, research", "pos": "noun"}, {"ko": "설문조사", "en": "survey", "pos": "noun"}, {"ko": "고급", "en": "high quality, advanced", "pos": "noun"}, {"ko": "주택", "en": "house, housing", "pos": "noun"}, {"ko": "희망자", "en": "applicant, hopeful", "pos": "noun"}, {"ko": "매출", "en": "sales", "pos": "noun"}, {"ko": "성적", "en": "grades", "pos": "noun"}, {"ko": "사원", "en": "employee", "pos": "noun"}, {"ko": "신입사원", "en": "new employee", "pos": "noun"}, {"ko": "편", "en": "counter for films/shows", "pos": "noun"}, {"ko": "부탁", "en": "favor", "pos": "noun"}, {"ko": "끈", "en": "string, lace", "pos": "noun"}, {"ko": "내버려두다", "en": "to leave alone", "pos": "verb"}, {"ko": "꼬다", "en": "to twist", "pos": "verb"}, {"ko": "가르다", "en": "to split, cut through", "pos": "verb"}, {"ko": "애쓰다", "en": "to strive, make an effort", "pos": "verb"}, {"ko": "개최하다", "en": "to host (an event)", "pos": "verb"}, {"ko": "입주하다", "en": "to move in", "pos": "verb"}, {"ko": "묶다", "en": "to tie", "pos": "verb"}, {"ko": "풀리다", "en": "to come untied", "pos": "verb"}, {"ko": "지치다", "en": "to be exhausted", "pos": "verb"}, {"ko": "풍부하다", "en": "to be abundant", "pos": "adjective"}, {"ko": "뜻밖에", "en": "unexpectedly", "pos": "adverb"}], "grammar": [{"point": "Quoted requests for oneself: ~(아/어) 달라고 하다", "explanation": "When someone asks for something to be given to them, Korean reports it with 달다, not 주다. Original 물 주세요 → quote 물을 달라고 했어요. 달다 only appears in quotes like this, never on its own.\n\nThe same happens with ~아/어 주다 'do something for me': 빌려 주세요 → 빌려 달라고. Step by step: verb + 아/어, then 달라고. 닫다 → 닫아 달라고. 읽다 → 읽어 달라고. 하다 → 해 달라고. 묶다 → 묶어 달라고.\n\nWhat matters is who benefits in the original sentence. If the original speaker asked for something for themselves, use 달라고, no matter who reports it later.\n\nTo report 'please don't...', use ~지 말아 달라고: 늦지 말아 달라고 했어요.", "examples": [{"ko": "동생이 저에게 물을 달라고 했어요.", "en": "My younger sibling asked me to give them water."}, {"ko": "친구가 저에게 돈을 빌려 달라고 했어요.", "en": "My friend asked me to lend him money."}, {"ko": "아이가 엄마에게 책을 읽어 달라고 했어요.", "en": "The child asked mom to read him a book."}, {"ko": "손님이 창문을 닫아 달라고 했어요.", "en": "The customer asked us to close the window."}, {"ko": "동생이 저에게 신발 끈을 묶어 달라고 했어요.", "en": "My younger sibling asked me to tie their shoelaces."}, {"ko": "할머니가 저에게 전화해 달라고 했어요.", "en": "Grandma asked me to call her.", "note": "하다 contracts: 하 + 여 → 해 달라고."}]}, {"point": "Giving to someone else: 주라고 하다", "explanation": "달라고 is only for 'give it to me', the original speaker. If the speaker told you to give something to someone else, use the normal command quote of 주다: 주 + 라고 → 주라고.\n\nCompare. Mom says '동생한테 과자 줘' → 엄마가 동생한테 과자를 주라고 했어요. Mom says '나한테 과자 줘' → 엄마가 과자를 달라고 했어요.\n\nThe same choice applies to ~아/어 주다. 도와 달라고 = asked me to help them. 도와주라고 = told me to help someone else.\n\nTip: look at who gets the item or the help. The original speaker → 달라고. Anyone else → 주라고.", "examples": [{"ko": "엄마가 저에게 동생한테 과자를 주라고 했어요.", "en": "Mom told me to give my younger sibling some snacks."}, {"ko": "선생님이 저에게 이 책을 민수에게 주라고 했어요.", "en": "The teacher told me to give this book to Minsu."}, {"ko": "친구가 저에게 그 편지를 여자 친구에게 주라고 했어요.", "en": "My friend told me to give that letter to his girlfriend."}, {"ko": "선생님이 저에게 민수를 도와주라고 했어요.", "en": "The teacher told me to help Minsu.", "note": "Minsu, not the teacher, gets the help, so it's 주라고."}, {"ko": "엄마가 저에게 강아지한테 물을 주라고 했어요.", "en": "Mom told me to give the dog some water."}, {"ko": "누구에게 이 돈을 주라고 했어요?", "en": "Who did they tell you to give this money to?"}]}, {"point": "Favor: 부탁 / 부탁하다", "explanation": "부탁 is a noun meaning a favor or a request. 부탁이 있어요 = I have a favor to ask. 부탁을 들어 주다 = to do someone a favor (literally, to listen to their request).\n\n부탁하다 is the verb 'to ask a favor'. The person you ask takes ~에게 or ~한테. What you ask for is often a quoted request: 도와 달라고 부탁했어요 = asked them to help me. It can also be a simple noun: 친구에게 강아지를 부탁했어요 = asked a friend to look after the dog.\n\nSet phrases you will hear a lot: 부탁해요 'I'm counting on you / please', and 잘 부탁드립니다 when you meet someone you'll work with.\n\nCompare: 물어보다 asks for information. 부탁하다 asks for help or an action.", "examples": [{"ko": "부탁이 하나 있어요.", "en": "I have a favor to ask."}, {"ko": "친구에게 이사를 도와 달라고 부탁했어요.", "en": "I asked my friend to help me move."}, {"ko": "제 부탁을 들어 줄 수 있어요?", "en": "Can you do me a favor?"}, {"ko": "여행 동안 친구에게 강아지를 부탁했어요.", "en": "I asked my friend to look after my dog during my trip."}, {"ko": "동생에게 제 방에 들어오지 말아 달라고 부탁했어요.", "en": "I asked my younger sibling not to come into my room.", "note": "'Please don't' in a quote is ~지 말아 달라고."}, {"ko": "부탁 하나만 들어 주세요.", "en": "Please do me just one favor."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "친구가 저에게 펜을 ___ 했어요.", "answer": "달라고", "options": ["달라고", "주라고", "줘라고", "달으라고"], "en": "My friend asked me to give him a pen.", "why": "The speaker wanted it for himself, so 주다 becomes 달라고."}, {"type": "fill", "ko": "동생이 저에게 신발 끈을 ___ 달라고 했어요.", "answer": "묶어", "options": ["묶어", "묶고", "묶으", "묶게"], "en": "My younger sibling asked me to tie his shoelaces.", "why": "A favor for the speaker is ~아/어 달라고: 묶어 달라고."}, {"type": "fill", "ko": "언니가 저에게 고양이한테 밥을 ___ 했어요.", "answer": "주라고", "options": ["주라고", "달라고", "줘라고", "주으라고"], "en": "My older sister told me to give food to the cat.", "why": "The cat, not my sister, gets the food, so the normal command quote 주라고."}, {"type": "fill", "ko": "손님이 직원에게 사진을 ___ 달라고 했어요.", "answer": "찍어", "options": ["찍어", "찍고", "찍으", "찍게"], "en": "The customer asked the employee to take a photo for her.", "why": "~아/어 달라고 reports a request to do something for the speaker."}, {"type": "fill", "ko": "친구에게 숙제를 도와 달라고 ___.", "answer": "부탁했어요", "options": ["부탁했어요", "부탁이었어요", "부탁됐어요", "부탁을했어요"], "en": "I asked my friend to help me with my homework.", "why": "부탁하다 is the verb 'to ask a favor' and often follows 달라고."}, {"type": "fill", "ko": "저는 친구에게 ___ 하나 있다고 했어요.", "answer": "부탁이", "options": ["부탁이", "부탁을", "부탁가", "부탁에"], "en": "I told my friend I had a favor to ask.", "why": "부탁 is the subject of 있다 and ends in a consonant, so 이."}, {"type": "fill", "ko": "선생님이 저에게 민수를 도와___ 하셨어요.", "answer": "주라고", "options": ["주라고", "달라고", "줘라고", "주으라고"], "en": "The teacher told me to help Minsu.", "why": "Minsu gets the help, not the teacher, so 도와주라고."}, {"type": "fill", "ko": "신입사원이 저에게 일을 ___ 달라고 했어요.", "answer": "가르쳐", "options": ["가르쳐", "가르치", "가르쳐서", "가르치고"], "en": "The new employee asked me to teach him the work.", "why": "가르치다 + 어 contracts to 가르쳐 before 달라고."}, {"type": "translate", "en": "My friend asked me to buy him coffee.", "ko": "친구가 저에게 커피를 사 달라고 했어요."}, {"type": "translate", "en": "Mom told me to give this book to my younger sibling.", "ko": "엄마가 저에게 이 책을 동생에게 주라고 하셨어요."}, {"type": "translate", "en": "I asked my older brother to tie the string.", "ko": "형에게 끈을 묶어 달라고 부탁했어요."}, {"type": "translate", "en": "The customer asked for water.", "ko": "손님이 물을 달라고 했어요."}], "reading": {"ko": "우리 회사에 신입사원이 왔어요. 그 사원의 이름은 지훈이에요. 지훈 씨는 일을 잘하려고 애써요. 어제 지훈 씨가 저에게 설문조사를 도와 달라고 부탁했어요. 그런데 저는 너무 바빴어요. 그래서 부장님이 그 일을 민수 씨에게 주라고 하셨어요. 민수 씨가 지훈 씨를 도와줬어요.", "en": "A new employee came to our company. His name is Jihun. Jihun tries hard to do his work well. Yesterday Jihun asked me to help him with a survey. But I was too busy. So the manager told me to give that job to Minsu. Minsu helped Jihun.", "questions": [{"q": "지훈 씨는 누구예요?", "a": "신입사원이에요."}, {"q": "지훈 씨는 무엇을 부탁했어요?", "a": "설문조사를 도와 달라고 부탁했어요."}, {"q": "부장님은 뭐라고 하셨어요?", "a": "그 일을 민수 씨에게 주라고 하셨어요."}]}}}, {"n": 56, "title": "Lesson 56: To make, to let: ~게 하다, ~게: so that", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-56/", "vocab": [{"ko": "부전공", "en": "minor (university)", "pos": "noun"}, {"ko": "형식", "en": "form, format", "pos": "noun"}, {"ko": "진로", "en": "career path", "pos": "noun"}, {"ko": "과정", "en": "process", "pos": "noun"}, {"ko": "축제", "en": "festival", "pos": "noun"}, {"ko": "목록", "en": "list", "pos": "noun"}, {"ko": "상점", "en": "store", "pos": "noun"}, {"ko": "시야", "en": "field of vision", "pos": "noun"}, {"ko": "도구", "en": "tool", "pos": "noun"}, {"ko": "햇빛", "en": "sunlight", "pos": "noun"}, {"ko": "도달하다", "en": "to reach", "pos": "verb"}, {"ko": "싣다", "en": "to load", "pos": "verb"}, {"ko": "둘러보다", "en": "to look around (have a browse)", "pos": "verb"}, {"ko": "들여다보다", "en": "to look into", "pos": "verb"}, {"ko": "내다보다", "en": "to look out", "pos": "verb"}, {"ko": "노크하다", "en": "to knock", "pos": "verb"}, {"ko": "성취하다", "en": "to achieve", "pos": "verb"}, {"ko": "싸다", "en": "to wrap", "pos": "verb"}, {"ko": "맞히다", "en": "to guess correctly", "pos": "verb"}, {"ko": "끼다", "en": "to put on (ring, gloves)", "pos": "verb"}, {"ko": "깨다", "en": "to wake up", "pos": "verb"}, {"ko": "싸이다", "en": "to be wrapped", "pos": "verb"}, {"ko": "날씬하다", "en": "to be slim", "pos": "adjective"}, {"ko": "더욱", "en": "more and more", "pos": "adverb"}], "grammar": [{"point": "To make / let someone do: ~게 하다", "explanation": "~게 하다 means 'make someone do', 'let someone do', or 'make something a certain way'. Korean uses the same form for forcing and allowing, so context decides the English.\n\nForm: stem + 게 하다, with no vowel/consonant split. Only 하다 changes for tense. 자다 → 자게 했어요. 먹다 → 먹게 해요. Adjectives describe the state you cause: 기쁘다 → 기쁘게 했어요 'made happy'.\n\nThe person made to act is usually marked with ~을/를 (저를 자게 했어요) or ~에게 (아이에게 채소를 먹게 해요). If the inside clause already has an object, the person often takes ~이/가: 동생이 게임을 못 하게 했어요.\n\n'Not let / stop someone' is 못 ~게 하다 or ~지 못하게 하다: 못 가게 했어요. ~지 않게 하다 means 'make sure something doesn't happen'.", "examples": [{"ko": "엄마가 저를 일찍 자게 했어요.", "en": "Mom made me go to bed early."}, {"ko": "선생님이 학생들을 집에 가게 했어요.", "en": "The teacher let the students go home."}, {"ko": "그 소식이 저를 놀라게 했어요.", "en": "That news surprised me."}, {"ko": "아빠가 동생이 게임을 못 하게 했어요.", "en": "Dad didn't let my younger sibling play games."}, {"ko": "친구의 편지가 저를 기쁘게 했어요.", "en": "My friend's letter made me happy.", "note": "With an adjective, ~게 하다 means 'make (someone) feel that way'."}, {"ko": "부모님이 아이에게 매일 채소를 먹게 해요.", "en": "The parents make their child eat vegetables every day."}]}, {"point": "So that / in a way that: ~게 + verb", "explanation": "Here ~게 is followed by an ordinary verb, not 하다, and means 'so that...' or 'in a way that...'. The ~게 clause comes first and gives the goal. The main verb says what you do to reach it.\n\nForm: stem + 게, with no vowel/consonant split: 보다 → 보게, 먹다 → 먹게. Two very common combinations:\n~(으)ㄹ 수 있게 'so that someone can': 볼 수 있게, 들을 수 있게.\n~지 않게 'so that something doesn't happen': 늦지 않게, 걸리지 않게.\n\nTense goes only on the final verb: 늦지 않게 일찍 출발했어요 (not 늦지 않았게).\n\nThis is the same ~게 that turns adjectives into adverbs: 크다 → 크게, 따뜻하다 → 따뜻하게. Compare ~(으)려고 (Lesson 32), which is about the subject's own intention. ~게 often aims at a result for someone else or for the situation.", "examples": [{"ko": "아이들이 잘 볼 수 있게 글씨를 크게 써 주세요.", "en": "Please write big so the kids can see well."}, {"ko": "다른 사람들이 들을 수 있게 크게 말해 주세요.", "en": "Please speak loudly so others can hear."}, {"ko": "늦지 않게 일찍 출발하세요.", "en": "Leave early so you are not late."}, {"ko": "비가 들어오지 않게 창문을 닫았어요.", "en": "I closed the window so the rain wouldn't come in."}, {"ko": "감기에 걸리지 않게 옷을 따뜻하게 입으세요.", "en": "Dress warmly so you don't catch a cold."}, {"ko": "동생이 잘 수 있게 텔레비전을 껐어요.", "en": "I turned off the TV so my younger sibling could sleep.", "note": "끄다 drops ㅡ: 끄 + 었어요 → 껐어요."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "아빠가 저를 매일 ___ 하셨어요.", "answer": "운동하게", "options": ["운동하게", "운동해게", "운동하기", "운동하고"], "en": "Dad made me exercise every day.", "why": "Stem + 게 하다 means 'make/let someone do'."}, {"type": "fill", "ko": "그 영화가 저를 ___ 했어요.", "answer": "울게", "options": ["울게", "우게", "울어게", "울기"], "en": "That movie made me cry.", "why": "The ㄹ of 울다 stays before 게."}, {"type": "fill", "ko": "동생이 깨지 않___ 작게 말해 주세요.", "answer": "게", "options": ["게", "기", "도", "지"], "en": "Please speak softly so my younger sibling doesn't wake up.", "why": "~지 않게 + verb means 'so that ... not'."}, {"type": "fill", "ko": "다른 사람들이 볼 수 있___ 목록을 문에 붙였어요.", "answer": "게", "options": ["게", "는", "기", "어"], "en": "I put the list on the door so other people could see it.", "why": "~ㄹ 수 있게 + verb means 'so that someone can'."}, {"type": "fill", "ko": "언니가 저에게 그 반지를 ___ 했어요.", "answer": "끼게", "options": ["끼게", "껴게", "끼기", "끼어게"], "en": "My older sister had me put on that ring.", "why": "게 attaches to the plain stem 끼, with no 어."}, {"type": "fill", "ko": "엄마가 저를 혼자 축제에 못 ___ 하셨어요.", "answer": "가게", "options": ["가게", "가기", "가서", "가고"], "en": "Mom didn't let me go to the festival alone.", "why": "못 ~게 하다 means 'not let someone do'."}, {"type": "fill", "ko": "이 음악은 사람들을 ___ 해요.", "answer": "행복하게", "options": ["행복하게", "행복해게", "행복하기", "행복히"], "en": "This music makes people happy.", "why": "Adjective stem + 게 하다 means 'make someone feel/be that way'."}, {"type": "fill", "ko": "감기에 걸리지 ___ 따뜻한 옷을 입으세요.", "answer": "않게", "options": ["않게", "않아", "않기", "말게"], "en": "Wear warm clothes so you don't catch a cold.", "why": "~지 않게 gives the purpose: 'so that ... not'."}, {"type": "translate", "en": "My friend made me laugh.", "ko": "친구가 저를 웃게 했어요."}, {"type": "translate", "en": "The teacher let us go home early.", "ko": "선생님이 우리를 일찍 집에 가게 하셨어요."}, {"type": "translate", "en": "I'll make a list so I don't forget.", "ko": "잊어버리지 않게 목록을 만들 거예요."}, {"type": "translate", "en": "That news made my mom sad.", "ko": "그 소식이 엄마를 슬프게 했어요."}], "reading": {"ko": "지난 주말에 우리 동네에서 축제가 있었어요. 엄마는 저와 동생을 축제에 가게 하셨어요. 축제에는 상점이 많았어요. 우리는 상점들을 천천히 둘러봤어요. 동생이 길을 잃지 않게 저는 동생의 손을 꼭 잡았어요. 동생은 과자를 하나 샀어요. 그 축제는 우리를 아주 즐겁게 했어요.", "en": "Last weekend there was a festival in our neighborhood. Mom let my younger sibling and me go to the festival. There were many stores at the festival. We slowly looked around the stores. I held my sibling's hand tightly so he wouldn't get lost. My sibling bought a snack. The festival made us very happy.", "questions": [{"q": "축제는 어디에서 있었어요?", "a": "우리 동네에서 있었어요."}, {"q": "왜 동생의 손을 잡았어요?", "a": "동생이 길을 잃지 않게 잡았어요."}, {"q": "축제는 어땠어요?", "a": "아주 즐거웠어요."}]}}}, {"n": 57, "title": "Lesson 57: To make/order: 시키다", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-57/", "vocab": [{"ko": "우리", "en": "cage, pen", "pos": "noun"}, {"ko": "다람쥐", "en": "squirrel", "pos": "noun"}, {"ko": "뱀", "en": "snake", "pos": "noun"}, {"ko": "실업", "en": "unemployment", "pos": "noun"}, {"ko": "실업자", "en": "unemployed person", "pos": "noun"}, {"ko": "초인종", "en": "doorbell", "pos": "noun"}, {"ko": "포대기", "en": "baby blanket", "pos": "noun"}, {"ko": "음주", "en": "drinking alcohol", "pos": "noun"}, {"ko": "금주", "en": "abstaining from alcohol", "pos": "noun"}, {"ko": "곁", "en": "one's side", "pos": "noun"}, {"ko": "심부름", "en": "errand", "pos": "noun"}, {"ko": "시키다", "en": "to order, make do", "pos": "verb"}, {"ko": "화해하다", "en": "to make up, reconcile", "pos": "verb"}, {"ko": "흥분하다", "en": "to get excited", "pos": "verb"}, {"ko": "자극하다", "en": "to stimulate", "pos": "verb"}, {"ko": "안정하다", "en": "to stabilize", "pos": "verb"}, {"ko": "응용하다", "en": "to apply (put knowledge to use)", "pos": "verb"}, {"ko": "차리다", "en": "to prepare (a meal); to recover", "pos": "verb"}, {"ko": "상기시키다", "en": "to remind", "pos": "verb"}, {"ko": "옮다", "en": "to catch (from someone, be infected)", "pos": "verb"}, {"ko": "옮기다", "en": "to move, transfer", "pos": "verb"}, {"ko": "불확실하다", "en": "to be uncertain", "pos": "adjective"}, {"ko": "간지럽다", "en": "to be ticklish", "pos": "adjective"}, {"ko": "방과후", "en": "after school", "pos": "other"}, {"ko": "대체로", "en": "generally", "pos": "adverb"}, {"ko": "당장", "en": "right now", "pos": "adverb"}, {"ko": "마음껏", "en": "as much as one likes", "pos": "adverb"}], "grammar": [{"point": "Noun + 시키다 (make someone do it)", "explanation": "Many 하다 verbs are a noun + 하다: 공부하다, 화해하다, 소개하다. Replace 하다 with 시키다 and the meaning becomes 'make or get someone to do it': 공부하다 'to study' → 공부시키다 'to make someone study'.\n\nThe person made to act takes ~을/를: 동생을 공부시켜요. Conjugate 시키다 like any verb: 시키 + 어요 → 시켜요, past 시켰어요.\n\nWith feeling verbs it means 'cause the feeling': 실망하다 'be disappointed' → 실망시키다 'disappoint someone'. 흥분하다 → 흥분시키다 'get someone excited'.\n\nIt means roughly the same as ~하게 하다 (Lesson 56): 공부시켜요 = 공부하게 해요. Not every 하다 verb can take 시키다, so learn the common ones. 소개시키다 is very common in speech, but 소개하다 is considered more standard.", "examples": [{"ko": "엄마가 동생을 매일 공부시켜요.", "en": "Mom makes my younger sibling study every day."}, {"ko": "제가 두 친구를 화해시켰어요.", "en": "I got my two friends to make up."}, {"ko": "그 소식이 부모님을 실망시켰어요.", "en": "That news disappointed my parents."}, {"ko": "부모님이 저를 그 학교에 입학시켰어요.", "en": "My parents enrolled me in that school.", "note": "입학하다 (to start at a school) → 입학시키다 (to enrol someone)."}, {"ko": "누가 아이들을 흥분시켰어요?", "en": "Who got the kids all excited?"}, {"ko": "친구가 저에게 약속을 상기시켜 줬어요.", "en": "My friend reminded me of the appointment.", "note": "상기시키다 is only used in its 시키다 form: A에게 B를 상기시키다."}]}, {"point": "시키다 as a verb: to order", "explanation": "On its own, 시키다 has two everyday meanings. At restaurants or for delivery it means 'to order' food or drinks: 피자를 시켰어요. This is the usual word in conversation; 주문하다 is more formal.\n\nIt also means 'to order someone to do a task': person + 에게, task + 을/를, then 시키다. Typical tasks are 일 (work), 심부름 (an errand) and 청소 (cleaning). 엄마가 저에게 청소를 시켰어요 = Mom had me clean.\n\nConjugation: 시키 + 어요 → 시켜요. Past 시켰어요. 'Shall we order?' 시킬까요?", "examples": [{"ko": "우리는 피자를 시켰어요.", "en": "We ordered pizza."}, {"ko": "엄마가 저에게 심부름을 시켰어요.", "en": "Mom sent me on an errand."}, {"ko": "부장님이 저에게 일을 많이 시켜요.", "en": "My manager gives me a lot of work."}, {"ko": "뭐 시킬까요?", "en": "What shall we order?"}, {"ko": "커피 두 잔을 시켰어요.", "en": "I ordered two cups of coffee."}, {"ko": "선생님이 학생들에게 청소를 시켰어요.", "en": "The teacher had the students clean up."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "선생님이 학생들을 매일 운동___.", "answer": "시키세요", "options": ["시키세요", "하세요", "되세요", "시켜하세요"], "en": "The teacher makes the students exercise every day.", "why": "Swap 하다 for 시키다 to make someone else do it."}, {"type": "fill", "ko": "그 경기는 사람들을 ___.", "answer": "흥분시켰어요", "options": ["흥분시켰어요", "흥분했어요", "흥분됐어요", "흥분시켜했어요"], "en": "That match got people excited.", "why": "With an object (사람들을), use 흥분시키다 'to excite someone'."}, {"type": "fill", "ko": "저녁에 피자를 ___?", "answer": "시킬까요", "options": ["시킬까요", "시켜까요", "시키을까요", "시킬래까요"], "en": "Shall we order pizza for dinner?", "why": "시키다 means 'to order food'; 시키 + ㄹ까요."}, {"type": "fill", "ko": "부장님이 신입사원___ 일을 많이 시키세요.", "answer": "에게", "options": ["에게", "을", "이", "에서"], "en": "The manager gives the new employee a lot of work.", "why": "The person given the task takes 에게."}, {"type": "fill", "ko": "의사 선생님이 환자를 먼저 ___.", "answer": "안정시키셨어요", "options": ["안정시키셨어요", "안정하셨어요", "안정되셨어요", "안정시켜셨어요"], "en": "The doctor stabilized the patient first.", "why": "안정하다 → 안정시키다 'to make someone stable'."}, {"type": "fill", "ko": "선생님이 학생들에게 시험 날짜를 ___.", "answer": "상기시키셨어요", "options": ["상기시키셨어요", "상기하셨어요", "상기되셨어요", "상기시켜셨어요"], "en": "The teacher reminded the students of the exam date.", "why": "상기시키다 'to remind' makes someone else recall something."}, {"type": "fill", "ko": "형과 제가 싸웠어요. 엄마가 우리를 ___.", "answer": "화해시키셨어요", "options": ["화해시키셨어요", "화해하셨어요", "화해되셨어요", "화해시켰셨어요"], "en": "My older brother and I fought. Mom got us to make up.", "why": "Mom made us make up, so 화해시키다."}, {"type": "fill", "ko": "음식을 너무 많이 ___ 다 못 먹었어요.", "answer": "시켜서", "options": ["시켜서", "시키서", "시켰어서", "시킬서"], "en": "We ordered too much food, so we couldn't eat it all.", "why": "시키 + 어서 contracts to 시켜서; tense is not marked before 아/어서."}, {"type": "translate", "en": "We ordered two coffees.", "ko": "우리는 커피 두 잔을 시켰어요."}, {"type": "translate", "en": "Dad sent my younger brother on an errand.", "ko": "아빠가 남동생에게 심부름을 시키셨어요."}, {"type": "translate", "en": "The teacher makes us study hard.", "ko": "선생님이 우리를 열심히 공부시키세요."}, {"type": "translate", "en": "Shall we order pizza right now?", "ko": "지금 당장 피자를 시킬까요?"}], "reading": {"ko": "오늘은 토요일이에요. 아침에 엄마가 저에게 심부름을 시키셨어요. 저는 가게에서 우유와 빵을 샀어요. 집에 와서 동생을 공부시켰어요. 동생은 공부를 싫어해요. 그래서 공부가 끝난 후에 동생을 마음껏 놀게 했어요. 저녁에는 가족들과 피자를 시켰어요. 피자는 아주 맛있었어요.", "en": "Today is Saturday. In the morning Mom sent me on an errand. I bought milk and bread at the store. When I came home, I made my younger sibling study. My sibling hates studying. So after studying was over, I let him play as much as he liked. In the evening we ordered pizza with the family. The pizza was very tasty.", "questions": [{"q": "엄마가 무엇을 시키셨어요?", "a": "심부름을 시키셨어요."}, {"q": "집에 와서 무엇을 했어요?", "a": "동생을 공부시켰어요."}, {"q": "저녁에 무엇을 시켰어요?", "a": "피자를 시켰어요."}]}}}, {"n": 58, "title": "Lesson 58: Or: ~(이)나, ~거나", "url": "https://www.howtostudykorean.com/unit-3-intermediate-korean-grammar/unit-3-lessons-51-58/lesson-58/", "vocab": [{"ko": "줄거리", "en": "plot, summary", "pos": "noun"}, {"ko": "체육관", "en": "gymnasium", "pos": "noun"}, {"ko": "조직", "en": "organization", "pos": "noun"}, {"ko": "양식", "en": "form (to fill out)", "pos": "noun"}, {"ko": "중간", "en": "middle", "pos": "noun"}, {"ko": "중간고사", "en": "midterm exam", "pos": "noun"}, {"ko": "중간지점", "en": "halfway point", "pos": "noun"}, {"ko": "기말고사", "en": "final exam", "pos": "noun"}, {"ko": "나머지", "en": "the rest", "pos": "noun"}, {"ko": "빈손", "en": "empty hands", "pos": "noun"}, {"ko": "채소", "en": "vegetables", "pos": "noun"}, {"ko": "기록하다", "en": "to record", "pos": "verb"}, {"ko": "등교하다", "en": "to go to school", "pos": "verb"}, {"ko": "하교하다", "en": "to leave school", "pos": "verb"}, {"ko": "고민하다", "en": "to agonise (over a decision)", "pos": "verb"}, {"ko": "활동하다", "en": "to be active, do activities", "pos": "verb"}, {"ko": "수정하다", "en": "to correct, modify", "pos": "verb"}, {"ko": "데려다 주다", "en": "to take someone somewhere", "pos": "verb"}, {"ko": "덧붙이다", "en": "to add on", "pos": "verb"}, {"ko": "살피다", "en": "to watch closely", "pos": "verb"}, {"ko": "차다", "en": "to kick", "pos": "verb"}, {"ko": "고치다", "en": "to fix, repair", "pos": "verb"}, {"ko": "반하다", "en": "to fall for (at first sight)", "pos": "verb"}, {"ko": "부지런하다", "en": "to be diligent", "pos": "adjective"}, {"ko": "희미하다", "en": "to be faint, dim", "pos": "adjective"}], "grammar": [{"point": "Noun or noun: ~(이)나", "explanation": "~(이)나 joins two nouns as choices: 'A or B'. Use it when either option is fine. Noun ends in a consonant → 이나: 빵 → 빵이나. Noun ends in a vowel → 나: 커피 → 커피나.\n\nOnly the first noun takes ~(이)나. The second takes whatever particle the sentence needs: 빵이나 밥을 먹어요 (object), 엄마나 아빠가 와요 (subject). Shared particles like ~에서, ~에 and ~(으)로 usually appear only after the last noun: 버스나 택시로, 체육관이나 공원에서.\n\nDon't confuse it with 'and'. ~하고 and ~와/과 mean both. ~(이)나 means one or the other.", "examples": [{"ko": "저는 빵이나 밥을 먹을 거예요.", "en": "I will eat bread or rice."}, {"ko": "엄마나 아빠가 저를 학교에 데려다 줄 거예요.", "en": "Mom or dad will take me to school."}, {"ko": "커피나 차를 드릴까요?", "en": "Shall I get you coffee or tea?"}, {"ko": "버스나 택시로 갈 거예요.", "en": "I'll go by bus or taxi."}, {"ko": "체육관이나 공원에서 운동해요.", "en": "I exercise at the gym or in the park.", "note": "~에서 comes only once, after the last noun."}, {"ko": "주말이나 방과후에 시간이 있어요?", "en": "Do you have time on the weekend or after school?"}]}, {"point": "Settling for something: ~(이)나 with one option", "explanation": "With only one noun, ~(이)나 changes meaning. It shows you are settling for something: it's not ideal, but it will do. English often uses 'just' or '... or something': 텔레비전이나 봐요 = Let's just watch TV.\n\nThe form is the same: consonant → 이나 (잠 → 잠이나), vowel → 나 (영화 → 영화나). It replaces 을/를 or 이/가.\n\nIt's common in suggestions and plans: ~(이)나 + ~(으)ㄹ까요?, ~아/어야겠어요, or ~(으)ㄹ 거예요.\n\nBecause it implies 'nothing better', be careful when offering something to a guest. 커피 드릴까요? is better than 커피나 드릴까요?, which can sound like 'want coffee or whatever?'.", "examples": [{"ko": "주말에는 집에서 텔레비전이나 봐요.", "en": "On weekends I just watch TV at home."}, {"ko": "점심은 라면이나 먹을까요?", "en": "Shall we just have ramen for lunch?"}, {"ko": "피곤해서 집에서 잠이나 자야겠어요.", "en": "I'm tired, so I guess I'll just sleep at home."}, {"ko": "주말에 영화나 볼까요?", "en": "Shall we just watch a movie this weekend?", "note": "영화 ends in a vowel, so it takes 나."}, {"ko": "비가 오면 집에서 책이나 읽을 거예요.", "en": "If it rains, I'll just read a book at home."}, {"ko": "피곤하면 커피나 마셔요.", "en": "If you're tired, just have a coffee."}]}, {"point": "Verb or verb: ~거나", "explanation": "~거나 joins two actions or descriptions as choices: 'do A or do B', 'is A or B'. It is the verb and adjective version of ~(이)나.\n\nForm: stem + 거나, with no vowel/consonant split: 읽다 → 읽거나, 쓰다 → 쓰거나, 피곤하다 → 피곤하거나. Only the last verb shows tense and politeness: 운동하거나 친구들과 놀았어요 = exercised or hung out with friends.\n\nYou can also say A거나 B거나 하다: 책을 읽거나 운동을 하거나 해요.\n\nDon't mix them up. Nouns use ~(이)나: 책이나 신문. Verbs and adjectives use ~거나: 책을 읽거나 신문을 봐요.", "examples": [{"ko": "주말에는 책을 읽거나 운동을 해요.", "en": "On weekends I read or exercise."}, {"ko": "친구에게 편지를 쓰거나 전화할 거예요.", "en": "I'll write my friend a letter or call him."}, {"ko": "피곤하거나 아프면 집에서 쉬세요.", "en": "If you're tired or sick, rest at home."}, {"ko": "저녁에는 음악을 듣거나 산책을 해요.", "en": "In the evening I listen to music or take a walk."}, {"ko": "학생 때는 방과후에 체육관에서 운동하거나 친구들과 놀았어요.", "en": "When I was a student, I worked out at the gym or hung out with friends after school.", "note": "The past tense goes only on the last verb: 놀았어요."}, {"ko": "모르는 단어가 있으면 사전을 찾거나 선생님께 물어보세요.", "en": "If there's a word you don't know, look it up in a dictionary or ask the teacher."}]}], "workbook": {"exercises": [{"type": "fill", "ko": "점심에는 김밥___ 라면을 먹어요.", "answer": "이나", "options": ["이나", "나", "거나", "으나"], "en": "For lunch I eat gimbap or ramen.", "why": "김밥 ends in a consonant, so 'or' is 이나."}, {"type": "fill", "ko": "주말에는 친구___ 동생과 같이 놀아요.", "answer": "나", "options": ["나", "이나", "거나", "니"], "en": "On weekends I hang out with a friend or my younger sibling.", "why": "친구 ends in a vowel, so 나."}, {"type": "fill", "ko": "저는 저녁에 책을 ___ 텔레비전을 봐요.", "answer": "읽거나", "options": ["읽거나", "읽나", "읽이나", "읽어나"], "en": "In the evening I read a book or watch TV.", "why": "Between two actions, 'or' is stem + 거나."}, {"type": "fill", "ko": "날씨가 ___ 비가 오면 집에서 운동해요.", "answer": "춥거나", "options": ["춥거나", "추우거나", "추워나", "춥이나"], "en": "If it's cold or it rains, I exercise at home.", "why": "거나 starts with a consonant, so 춥다 keeps its ㅂ."}, {"type": "fill", "ko": "오늘은 할 일이 없어요. 집에서 영화___ 볼까요?", "answer": "나", "options": ["나", "이나", "거나", "니"], "en": "There's nothing to do today. Shall we just watch a movie at home?", "why": "One noun + (이)나 means 'just ... I guess'; 영화 ends in a vowel."}, {"type": "fill", "ko": "주스가 없어요. 물___ 마셔야겠어요.", "answer": "이나", "options": ["이나", "나", "거나", "을나"], "en": "There's no juice. I guess I'll just drink water.", "why": "물 ends in a consonant, so the 'settling' form is 이나."}, {"type": "fill", "ko": "버스___ 지하철로 갈 거예요.", "answer": "나", "options": ["나", "에나", "거나", "이나"], "en": "I'll go by bus or subway.", "why": "With (이)나, the particle 로 appears only after the second noun."}, {"type": "fill", "ko": "숙제를 하___ 집을 청소할 거예요.", "answer": "거나", "options": ["거나", "나", "이나", "거니"], "en": "I'll do my homework or clean the house.", "why": "하다 is a verb, so 'or' is 거나, not (이)나."}, {"type": "translate", "en": "Shall we meet on Saturday or Sunday?", "ko": "토요일이나 일요일에 만날까요?"}, {"type": "translate", "en": "After school I go to the gym or the library.", "ko": "방과 후에 체육관이나 도서관에 가요."}, {"type": "translate", "en": "When I have worries, I talk with a friend or walk alone.", "ko": "고민이 있으면 친구와 이야기하거나 혼자 걸어요."}, {"type": "translate", "en": "Let's just eat at home today.", "ko": "오늘은 집에서 밥이나 먹어요."}], "reading": {"ko": "다음 주에 중간고사가 있어요. 그래서 요즘 저는 도서관에서 공부하거나 친구들과 같이 공부해요. 저녁에는 김밥이나 라면을 먹어요. 시간이 없어서 요리를 못 해요. 오늘은 너무 피곤해요. 그래서 오늘 밤에는 공부하지 않고 잠이나 자야겠어요. 시험이 끝나면 영화를 보거나 여행할 거예요.", "en": "Next week I have midterm exams. So these days I study at the library or study together with friends. In the evening I eat gimbap or ramen. I have no time, so I can't cook. Today I'm very tired. So tonight I won't study; I guess I'll just sleep. When the exams are over, I'll watch a movie or travel.", "questions": [{"q": "다음 주에 무엇이 있어요?", "a": "중간고사가 있어요."}, {"q": "저녁에는 무엇을 먹어요?", "a": "김밥이나 라면을 먹어요."}, {"q": "시험이 끝나면 무엇을 할 거예요?", "a": "영화를 보거나 여행할 거예요."}]}}}]);
